use serde::{Deserialize, Serialize};
use std::borrow::Cow;
use std::collections::BTreeMap;
use std::sync::OnceLock;

pub use crate::game_module_assembly::ExecutionCompatibility;
use crate::game_module_assembly::{AssembledFile, COMPATIBILITY_FILE, MANIFEST_FILE};

pub struct BundledFile {
    path: &'static str,
    sha256: &'static str,
    bytes: &'static [u8],
}

// Generated by build.rs from game-module/ and stamped with the planner version.
include!(concat!(env!("OUT_DIR"), "/game_module_package.rs"));

#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum PackageSource {
    Bundled,
    Checkout,
}

pub struct PackageFile {
    pub path: String,
    pub sha256: String,
    pub bytes: Cow<'static, [u8]>,
}

pub struct ModulePackage {
    pub version: String,
    pub source: PackageSource,
    pub files: Vec<PackageFile>,
    pub dependencies: Vec<String>,
    /// The plan header this package's module admits.
    pub compatibility: ExecutionCompatibility,
}

#[derive(Deserialize)]
struct PackageManifest {
    version_number: String,
    #[serde(default)]
    dependencies: Vec<String>,
}

impl ModulePackage {
    fn new(version: &str, source: PackageSource, files: Vec<PackageFile>) -> Result<Self, String> {
        let manifest = files
            .iter()
            .find(|file| file.path == MANIFEST_FILE)
            .ok_or("the game module package has no manifest")?;
        let manifest: PackageManifest = serde_json::from_slice(&manifest.bytes)
            .map_err(|error| format!("the game module manifest is malformed: {error}"))?;
        if manifest.version_number != version {
            return Err("the game module manifest is not stamped with the planner version".into());
        }
        let compatibility = files
            .iter()
            .find(|file| file.path == COMPATIBILITY_FILE)
            .ok_or("the game module package has no compatibility file")?;
        let compatibility: ExecutionCompatibility = serde_json::from_slice(&compatibility.bytes)
            .map_err(|error| format!("the game module compatibility file is malformed: {error}"))?;
        Ok(Self {
            version: version.to_owned(),
            source,
            files,
            dependencies: manifest.dependencies,
            compatibility,
        })
    }

    pub fn bundled() -> &'static ModulePackage {
        static PACKAGE: OnceLock<ModulePackage> = OnceLock::new();
        PACKAGE.get_or_init(|| {
            let files = BUNDLED_FILES
                .iter()
                .map(|file| PackageFile {
                    path: file.path.to_owned(),
                    sha256: file.sha256.to_owned(),
                    bytes: Cow::Borrowed(file.bytes),
                })
                .collect();
            ModulePackage::new(BUNDLED_VERSION, PackageSource::Bundled, files)
                .expect("build.rs embeds a valid game module package")
        })
    }

    pub fn from_assembly(
        version: &str,
        source: PackageSource,
        files: Vec<AssembledFile>,
    ) -> Result<Self, String> {
        let files = files
            .into_iter()
            .map(|file| PackageFile {
                path: file.path,
                sha256: file.sha256,
                bytes: Cow::Owned(file.bytes),
            })
            .collect();
        Self::new(version, source, files)
    }

    pub fn hashes(&self) -> BTreeMap<String, String> {
        self.files
            .iter()
            .map(|file| (file.path.clone(), file.sha256.clone()))
            .collect()
    }
}

/// Assembles the module from this build's `game-module/` checkout.
#[cfg(debug_assertions)]
pub fn checkout_package() -> Result<ModulePackage, String> {
    let module_dir =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../../game-module");
    ModulePackage::from_assembly(
        BUNDLED_VERSION,
        PackageSource::Checkout,
        crate::game_module_assembly::assemble(
            &module_dir,
            BUNDLED_VERSION,
            crate::game_module_assembly::ModuleSelection::DevelopmentIfPresent,
        )?,
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::game_module_assembly::{self, ModuleSelection};
    use std::fs;
    use std::path::Path;

    fn write(path: &Path, bytes: &[u8]) {
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, bytes).unwrap();
    }

    fn module_checkout(root: &Path) {
        write(
            &root.join("manifest.template.json"),
            br#"{"namespace":"adamantRunPlanner","name":"Run_Planner","description":"d","dependencies":["adamant-ModpackLib-4.2.0"],"website_url":"https://example.invalid","FullName":"adamantRunPlanner-Run_Planner"}"#,
        );
        for name in ["icon.png", "LICENSE", "README.md"] {
            write(&root.join(name), name.as_bytes());
        }
        write(&root.join("src/main.lua"), b"return true\n");
        write(&root.join("src/mods/a.lua"), b"return 1\n");
        write(
            &root.join("src/execution-compatibility.json"),
            COMPATIBILITY,
        );
    }

    const COMPATIBILITY: &[u8] = br#"{"format":"run-planner-execution","catalogVersion":"c","schemaVersion":96,"schemaRevision":0}"#;

    #[test]
    fn assembly_is_deterministic_flattened_and_version_stamped() {
        let root =
            std::env::temp_dir().join(format!("run-planner-assembly-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        module_checkout(&root);
        let first =
            game_module_assembly::assemble(&root, "2.3.4", ModuleSelection::Release).unwrap();
        let second =
            game_module_assembly::assemble(&root, "2.3.4", ModuleSelection::Release).unwrap();
        let paths: Vec<&str> = first.iter().map(|file| file.path.as_str()).collect();
        assert_eq!(
            paths,
            [
                "LICENSE",
                "README.md",
                "execution-compatibility.json",
                "icon.png",
                "main.lua",
                "manifest.json",
                "mods/a.lua"
            ]
        );
        for (left, right) in first.iter().zip(&second) {
            assert_eq!(left.bytes, right.bytes);
            assert_eq!(left.sha256, game_module_assembly::sha256_hex(&left.bytes));
        }
        let package =
            ModulePackage::from_assembly("2.3.4", PackageSource::Checkout, first).unwrap();
        assert_eq!(package.dependencies, ["adamant-ModpackLib-4.2.0"]);
        let compatibility = package
            .files
            .iter()
            .find(|file| file.path == "execution-compatibility.json")
            .unwrap();
        assert_eq!(compatibility.bytes.as_ref(), COMPATIBILITY);
        assert_eq!(
            package.compatibility,
            ExecutionCompatibility {
                format: "run-planner-execution".to_owned(),
                catalog_version: "c".to_owned(),
                schema_version: 96,
                schema_revision: 0,
            }
        );
        assert!(game_module_assembly::assemble(&root, "2.3", ModuleSelection::Release).is_err());
        write(&root.join("src/LICENSE"), b"collision");
        assert!(game_module_assembly::assemble(&root, "2.3.4", ModuleSelection::Release).is_err());
        fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn assembly_ships_only_a_complete_checked_in_compatibility_file() {
        let root =
            std::env::temp_dir().join(format!("run-planner-compatibility-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        module_checkout(&root);
        for malformed in [
            &br#"{"format":"run-planner-execution","catalogVersion":"c"}"#[..],
            br#"{"format":"run-planner-execution","catalogVersion":"c","schemaVersion":96,"schemaRevision":0,"buildId":"x"}"#,
        ] {
            write(&root.join("src/execution-compatibility.json"), malformed);
            assert!(
                game_module_assembly::assemble(&root, "2.3.4", ModuleSelection::Release)
                    .err()
                    .unwrap()
                    .contains("execution-compatibility.json is malformed")
            );
        }
        fs::remove_file(root.join("src/execution-compatibility.json")).unwrap();
        assert!(game_module_assembly::assemble(&root, "2.3.4", ModuleSelection::Release).is_err());
        fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn module_selection_replaces_the_release_modules_when_development_is_selected() {
        let root = std::env::temp_dir().join(format!("run-planner-variant-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        module_checkout(&root);
        for (module, _) in game_module_assembly::DEVELOPMENT_OVERRIDES {
            write(&root.join("src").join(module), b"return 'release'\n");
        }
        let assembled = |selection| {
            let files = game_module_assembly::assemble(&root, "2.3.4", selection)?;
            Ok::<_, String>(
                game_module_assembly::DEVELOPMENT_OVERRIDES
                    .iter()
                    .map(|(module, _)| {
                        files
                            .iter()
                            .find(|file| file.path == *module)
                            .unwrap()
                            .bytes
                            .clone()
                    })
                    .collect::<Vec<_>>(),
            )
        };
        let release = assembled(ModuleSelection::Release).unwrap();
        assert!(release.iter().all(|bytes| bytes == b"return 'release'\n"));
        assert_eq!(
            assembled(ModuleSelection::DevelopmentIfPresent).unwrap(),
            release
        );
        assert_eq!(
            assembled(ModuleSelection::DevelopmentRequired).unwrap_err(),
            "VITE_INTERNAL_FEATURES=1 requires the development module variant variants/dev/row_options.lua"
        );

        for (_, development) in game_module_assembly::DEVELOPMENT_OVERRIDES {
            write(&root.join(development), b"return 'dev'\n");
        }
        let dev = assembled(ModuleSelection::DevelopmentIfPresent).unwrap();
        assert!(dev.iter().all(|bytes| bytes == b"return 'dev'\n"));
        assert_eq!(
            assembled(ModuleSelection::DevelopmentRequired).unwrap(),
            dev
        );
        assert_eq!(assembled(ModuleSelection::Release).unwrap(), release);
        fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn embedded_package_is_the_stamped_plugin_folder() {
        let package = ModulePackage::bundled();
        assert_eq!(package.version, BUNDLED_VERSION);
        let manifest: serde_json::Value = serde_json::from_slice(
            &package
                .files
                .iter()
                .find(|file| file.path == MANIFEST_FILE)
                .unwrap()
                .bytes,
        )
        .unwrap();
        assert_eq!(manifest["version_number"], BUNDLED_VERSION);
        assert_eq!(manifest["FullName"], "adamantRunPlanner-Run_Planner");
        for required in [
            "main.lua",
            "execution-compatibility.json",
            "icon.png",
            "LICENSE",
            "mods/presentation/status_ui.lua",
        ] {
            assert!(package.files.iter().any(|file| file.path == required));
        }
        let mut paths: Vec<&str> = package
            .files
            .iter()
            .map(|file| file.path.as_str())
            .collect();
        let listed = paths.clone();
        paths.sort_unstable();
        assert_eq!(paths, listed);
        for file in &package.files {
            assert_eq!(file.sha256, game_module_assembly::sha256_hex(&file.bytes));
        }
        assert!(package
            .dependencies
            .iter()
            .any(|dependency| dependency.starts_with("adamant-ModpackLib-")));
        #[cfg(debug_assertions)]
        assert_eq!(
            checkout_package().unwrap().compatibility,
            package.compatibility
        );
    }
}
